import { render, screen, within } from "@testing-library/react";
import { beforeEach, describe, expect, it, vi } from "vitest";

// The data the API actually serves (generated by eval/dashboard.py).
import EVALUATIONS from "../../../../api/src/facelens_api/ml/evaluations.json";
import { EvaluationDashboard } from "@/components/evaluation/evaluation-dashboard";
import { metricDomain } from "@/components/evaluation/group-chart";
import type { EvaluationMetric } from "@/lib/api/client";
import { describeCriterion, formatLimit, formatValue } from "@/lib/evaluation";

const mock = (task: string, id: string, candidate: string, status: string) => ({
  task,
  enabled: true,
  model: { id, version: "0.1.0", is_mock: true, license: "n/a", source_url: null, intended_use: "dev", limitations: [], eval_passed: false, eval_report: null },
  candidate: { task, model_id: candidate, model_name: candidate.split("@")[0], status, report: null, dataset: null, evaluated_at: null, n: null, criteria: [] },
});

const CAPS = {
  face_detection: { enabled: true, model_id: "yunet", version: "2026may", license: "MIT", source_url: null, min_face_side: 64, policy: "" },
  features: [
    mock("age_estimation", "mock-age-estimator", "MiVOLO v2@1", "failed"),
    mock("presentation_estimation", "mock-presentation-estimator", "MiVOLO v2@1", "failed"),
    mock("age_transformation", "mock-age-transformer", "SAM@1", "not_evaluated"),
  ],
};

const json = (body: unknown) => new Response(JSON.stringify(body), { status: 200, headers: { "Content-Type": "application/json" } });

beforeEach(() => {
  vi.stubGlobal(
    "fetch",
    vi.fn(async (url: string) => (url === "/v1/evaluations" ? json(EVALUATIONS) : json(CAPS))),
  );
});

describe("EvaluationDashboard", () => {
  it("shows every tool's gate outcome and that the tools run on mocks", async () => {
    render(<EvaluationDashboard />);
    const demo = await screen.findByRole("note", { name: /demo status/i });
    expect(demo).toHaveTextContent(/All 3 tools run on mock models/);
    expect(demo).toHaveTextContent(/Age estimate: the real candidate, MiVOLO v2, was evaluated and failed/);
    expect(demo).toHaveTextContent(/Age transformation preview: the real candidate, SAM, hasn't been evaluated yet/);

    const age = screen.getByRole("region", { name: /^Age estimate: MiVOLO v2/ });
    expect(within(age).getByText("Failed release gates")).toBeInTheDocument();
    const limits = within(age).getByRole("table", { name: /release limits/i });
    const coverage = within(limits).getByRole("row", { name: /range coverage/i });
    expect(coverage).toHaveTextContent("≥ 70.0%");
    expect(coverage).toHaveTextContent("67.9% for the 40–49 age group");
    expect(coverage).toHaveTextContent("Fail");

    const detection = screen.getByRole("region", { name: /^Face detection: YuNet/ });
    expect(within(detection).getByText("Passed release gates")).toBeInTheDocument();
    const aging = screen.getByRole("region", { name: /^Age transformation preview: SAM/ });
    expect(within(aging).getAllByText("Not measured").length).toBeGreaterThan(0);

    // Per-group charts are tables with the numbers in text, and flag groups past the limit.
    const raceCoverage = within(age).getByRole("figure", { name: /^Range coverage.*by annotated race$/ });
    expect(within(raceCoverage).getByRole("rowheader", { name: "Black" })).toBeInTheDocument();
    const ageBins = within(age).getByRole("figure", { name: /^Range coverage.*by annotated age$/ });
    expect(within(ageBins).getByRole("row", { name: /40-49/ })).toHaveTextContent(/Beyond the release limit/);
  });

  it("reports a load failure", async () => {
    vi.stubGlobal("fetch", vi.fn(async () => new Response("{}", { status: 500 })));
    render(<EvaluationDashboard />);
    expect(await screen.findByRole("alert")).toHaveTextContent(/couldn.t load the evaluation results/i);
  });
});

describe("evaluation formatting", () => {
  it("formats each value kind", () => {
    expect(formatValue(0.6785, "percent")).toBe("67.9%");
    expect(formatValue(0.0044, "percent")).toBe("0.44%");
    expect(formatValue(0.0289, "pp")).toBe("2.9 pp");
    expect(formatValue(1.551, "ratio")).toBe("1.55×");
    expect(formatValue(1.903, "years")).toBe("1.9 years");
    expect(formatLimit({ comparator: "max", limit: 1.5, format: "ratio" })).toBe("≤ 1.50×");
  });

  it("describes measured and unmeasured criteria", () => {
    const base = { id: "x", label: "Adults wrongly blocked", format: "percent" as const, comparator: "max" as const, limit: 0.01, by_family: [] };
    expect(
      describeCriterion({ ...base, measured: 0.0279, worst_family: "race", worst_group: "Black", passed: false }),
    ).toBe("Adults wrongly blocked: 2.8% for faces annotated as Black (limit ≤ 1.0%)");
    expect(describeCriterion({ ...base, measured: null, worst_family: null, worst_group: null, passed: null })).toBe(
      "Adults wrongly blocked (limit ≤ 1.0%): not measured yet",
    );
  });

  it("keeps the overall value and release limit inside the chart scale", () => {
    const metric: EvaluationMetric = {
      id: "coverage",
      label: "",
      format: "percent",
      higher_is_better: true,
      overall: 0.79,
      gate_threshold: 0.7,
      families: [{ family: "race", label: "", groups: [{ group: "A", n: 1, value: 0.8, ci95: [0.75, 0.85] }] }],
    };
    const { lo, hi } = metricDomain(metric);
    expect(lo).toBeLessThan(0.7);
    expect(hi).toBeGreaterThan(0.85);
    expect(hi).toBeLessThanOrEqual(1);
  });
});
